-- =====================================================================
--  FUTH Lafia EMR — v2.3 Service Entity Update
--  NHIA Procedure Price List 2025 (April 2025) for BOTH NHIS (federal
--  NHIA) and NASHIA (Nasarawa State) + special non-clinical services
-- ---------------------------------------------------------------------
--  Import via phpMyAdmin → select database → Import tab → choose this
--  file → Go.  The file is IDEMPOTENT: every statement is guarded, so it
--  is safe to run more than once (prices are refreshed, no duplicates).
--
--  It is the SQL equivalent of:
--    php artisan migrate            (migration 2026_11_03_000001_…)
--    php artisan db:seed --class=NhiaPriceList2025Seeder
--    php artisan db:seed --class=SpecialServicesSeeder
--
--  Generated: 2026-11-02 18:55
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

-- =====================================================================
-- 1. SCHEMA CHANGES
-- =====================================================================

-- 1a. services.nashia_rate — NASHIA (Nasarawa State) tariff
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'services' AND COLUMN_NAME = 'nashia_rate');
SET @s := IF(@c = 0, 'ALTER TABLE `services` ADD COLUMN `nashia_rate` DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER `nhia_rate`', 'SELECT "nashia_rate exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1b. services.allowed_roles — JSON list of roles permitted to bill the service
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'services' AND COLUMN_NAME = 'allowed_roles');
SET @s := IF(@c = 0, 'ALTER TABLE `services` ADD COLUMN `allowed_roles` JSON NULL AFTER `requires_pre_authorization`', 'SELECT "allowed_roles exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1c. services.allows_walk_in — billable to walk-in (non-patient) customers
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'services' AND COLUMN_NAME = 'allows_walk_in');
SET @s := IF(@c = 0, 'ALTER TABLE `services` ADD COLUMN `allows_walk_in` TINYINT(1) NOT NULL DEFAULT 0 AFTER `allowed_roles`', 'SELECT "allows_walk_in exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1d. index on services.nhia_code
SET @c := (SELECT COUNT(*) FROM information_schema.STATISTICS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'services' AND INDEX_NAME = 'services_nhia_code_index');
SET @s := IF(@c = 0, 'ALTER TABLE `services` ADD INDEX `services_nhia_code_index` (`nhia_code`)', 'SELECT "nhia_code index exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1e. invoices.customer_name / customer_phone — walk-in customers
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'invoices' AND COLUMN_NAME = 'customer_name');
SET @s := IF(@c = 0, 'ALTER TABLE `invoices` ADD COLUMN `customer_name` VARCHAR(255) NULL AFTER `patient_insurance_id`', 'SELECT "customer_name exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'invoices' AND COLUMN_NAME = 'customer_phone');
SET @s := IF(@c = 0, 'ALTER TABLE `invoices` ADD COLUMN `customer_phone` VARCHAR(30) NULL AFTER `customer_name`', 'SELECT "customer_phone exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1f. invoices.patient_id nullable (walk-in customers are not patients)
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'invoices' AND COLUMN_NAME = 'patient_id' AND IS_NULLABLE = 'NO');
SET @s := IF(@c > 0, 'ALTER TABLE `invoices` MODIFY `patient_id` BIGINT UNSIGNED NULL', 'SELECT "patient_id already nullable"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1g. invoices.payment_mode gains NASHIA (state scheme)
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'invoices' AND COLUMN_NAME = 'payment_mode'
             AND COLUMN_TYPE LIKE '%NASHIA%');
SET @s := IF(@c = 0, "ALTER TABLE `invoices` MODIFY `payment_mode` ENUM('Cash','Insurance','NHIA','NASHIA','Corporate','Charity','Mixed') NOT NULL DEFAULT 'Cash'", 'SELECT "NASHIA payment mode exists"');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;


